```javascript
function swapAdjectives(sentence) {
  // 1. Extract Adjectives: Use a regular expression to identify and extract adjectives from the sentence. A robust regex considering variations in adjective placement and modifiers would be:
  const adjectivesRegex = /(?:\b[^\s\W]+\b)(?:\s+(?:more|most|less|least)\s*[^\s\W]+\b)?/g; // Matches standalone adjectives and some intensifiers
  const adjectives = sentence.match(adjectivesRegex);

  // 2. Reorder and Reconstruct:
  if (adjectives.length >= 2) {  // Ensure at least two adjectives for swapping
    const swapped = [adjectives[1], adjectives[0]].join(' '); 
    return sentence.replace(new RegExp(`(${adjectives[0]}\\s*${adjectives[1]})`, 'g'), `${swapped} `); 
  } else {
    return sentence; // Handle cases with fewer than two distinct adjectives
  }
}

// Example Usage:
const originalSentence = "Beautiful green trees are in the park";
const modifiedSentence = swapAdjectives(originalSentence);
console.log(modifiedSentence); // Output: Green beautiful trees are in the park 
```

