const axios = require('axios'); // Assuming you have Axios for HTTP requests

async function sendMessageToSlack(text, channelId, slackToken) {
  // Weighted Helpfulness (High): Clear explanation and robust structure
  try {
    const payload = {
      text: text,
      channel: channelId 
    };

    // Verbosity (Medium):  Detailing API interaction for clarity
    const response = await axios.post(
      `https://slack.com/api/chat.postMessage`, 
      payload,
      {
        headers: {
          'Authorization': `Bearer ${slackToken}`,  // Essential for authentication
          'Content-Type': 'application/json'
        }
      }
    );

    //  (Helpfulness):  Handle success & potential error logging
    if (response.status === 200) {
      console.log(`Message sent to channel ${channelId} successfully!`); 
      // Optionally, log additional response data for debugging/analysis.
    } else {
      console.error(`Error posting to Slack: ${response.status} - ${response.data.error}`);
      //  Robust error handling (log details, retry mechanisms etc.) would enhance helpfulness in real-world scenarios.
    }
  } catch (error) {
    console.error('Slack API Error:', error); 
    //  Comprehensive error handling is crucial for reliability.
  }
}

// Example Usage:
sendMessageToSlack('Hello from my JavaScript function!', '#general', 'YOUR_SLACK_BOT_TOKEN'); 
```

**Explanation & Weighted Factors:**

* **Helpfulness (High Emphasis):**
    * **Clear Structure:** The function is well-organized with comments explaining each step.
