using namespace std;

// Recursive Fibonacci function with error handling
int fibonacci(int a, int b, int n, bool& isValid) {
    if (n <= 0) {  // Base case: Handle invalid sequence length
        isValid = false;
        return -1; 
    } else if (n == 1) {
        return a;
    } else if (n == 2) {
        return b;
    } else {
        int next = fibonacci(b, a + b, n - 1, isValid);
        return isValid ? next : -1; // Propagate validity status
    }
}

