using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json; // Or your preferred JSON serialization library

public class RestServiceWrapper<T> where T : class
{
    private readonly HttpClient _client;
    private readonly string _baseUrl;
    private string _authToken;

    public RestServiceWrapper(string baseUrl, string initialAuthToken = null)
    {
        _baseUrl = baseUrl;
        _authToken = initialAuthToken;
        _client = new HttpClient { BaseAddress = new Uri(_baseUrl) };
        // Add default headers for easier management (e.g., Content-Type)
        _client.DefaultRequestHeaders.Add("Accept", "application/json"); 
    }

    /// <summary>
    /// Sets a new authentication token for subsequent requests.
    /// </summary>
    public void SetAuthToken(string token) => _authToken = token;

    /// <summary>
    ///  Generic GET request handler with auth token injection.
    /// </summary>
    public async Task<T> GetAsync(string endpoint, params (string key, object value)[] queryParameters)
    {
        var uriBuilder = new UriBuilder(_baseUrl + endpoint);
        if (queryParameters.Length > 0)
        {
            var query = HttpUtility.ParseQueryString(uriBuilder.Query);
            foreach (var (key, value) in queryParameters)
                query[key] = value.ToString();
            uriBuilder.Query = query.ToString();
        }

        return await AddAuthAndExecute<T>(HttpMethod.Get, uriBuilder.Uri);
    }

    /// <summary>
    /// Generic POST request handler with auth token and data serialization.
    /// </summary>
    public async Task<T> PostAsync<TData>(string endpoint, TData data)
        where TData : class
    {
        var content = JsonConvert.SerializeObject(data);
        return await AddAuthAndExecute<T>(HttpMethod.Post, endpoint, content);
    }

