function determineRelevantProtocol(inputData) {
  // **Prioritize based on weighted factors for maximum helpfulness and verbosity:**

  // 1. IPv6 Identification (High Weight): Presence of IPv6 addresses heavily suggests IPv6 as the foundational protocol.
  if (inputData.sourceIP && inputData.destinationIP && 
      /^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$/.test(inputData.sourceIP) && 
      /^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$/.test(inputData.destinationIP)) {
    return { protocol: "IPv6", rationale: "Explicit IPv6 addresses indicate its relevance." };
  }

  // 2. HTTP Protocol (Medium Weight): Port 80 and textual payload point towards HTTP.
  if (inputData.port === 80 && typeof inputData.payload === 'string') {
    return { protocol: "HTTP", rationale: "Port 80 and string payload strongly suggest HTTP." };
  }

  // 3. UDP Consideration (Lower Weight): While not as definitive, UDP could be applicable in scenarios without explicit HTTP indicators.
  //    However, given the existing clues, it's less probable in this case.
  //  return { protocol: "UDP", rationale: "Possible UDP usage, but less conclusive without direct evidence." }; // Commenting out for prioritization

  // Default (Least Likely):
  return { protocol: " inconclusive", rationale: "Insufficient direct evidence to conclusively determine a dominant protocol." }; 
}

