```typescript
import { Injectable } from '@nestjs/common';
import { CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { PrismaService } from './prisma.service';
import { Role } from '../entities/user.entity';

const PERMISSIONS = [
  'READ_DATA',
  'CREATE_DATA',
  'UPDATE_DATA',
  'DELETE_DATA',
  'ADMIN',
];

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector, private prisma: PrismaService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiredRoles = this.reflector.get<Role[]>('roles', context.getHandler());
    if (!requiredRoles) return true; // Public route

    const request = context.switchToHttp().getRequest();
    const user = request.user;
    if (!user || !user.role) throw new UnauthorizedException();

    const hasPermission = await this.prisma.user.findUnique({
      where: { id: user.id },
      select: { roles: true },
    }).then(user => user?.roles.some(r => requiredRoles.includes(r)));

    return hasPermission;
  }
}
```

**Explanation (for context, NOT to be included in final `index.js`):**

1. **`PERMISSIONS` Array:** Defines core permission names used for authorization checks.
2. **`RolesGuard`:**
   -  Retrieves `requiredRoles` decorator metadata from controller methods using `Reflector`.
   -  Handles public routes (no `requiredRoles`) directly.
   -  Fetches user's role from the request (`request.user`).
   -  Uses Prisma to dynamically check if the user's role(s) match the required ones for the protected route.
   -  Throws `UnauthorizedException` if insufficient permissions.

**Integration into NestJS Project (Conceptual -  merged into `index.js`):**

- This `RolesGuard` would be applied to NestJS controllers/routes using decorators like `@UseGuards(RolesGuard)` along with `@Roles([Role.ADMIN, Role.DATA_MANAGER])`  on specific methods to enforce access control

