/**
 * Searches for a place name in a specified column and retrieves latitude/longitude, storing them in designated columns.
 *
 * @param {string} spreadsheetId  - ID of the Google Sheet containing your data.
 * @param {string} sheetName      - Name of the sheet with the data (e.g., "Locations").
 * @param {string} placeNameColumn - Header of the column containing place names to search (e.g., "Place").
 * @param {string} latColumn      - Header of the column to store retrieved latitudes.
 * @param {string} lngColumn      - Header of the column to store retrieved longitudes.
 * @param {function(string):string} geocodingService  -  A custom function (see explanation below) to handle Geocoding API calls for more flexibility. Defaults to Apps Script's built-in geocoding.
 */
function fetchLatLngFromPlaces(spreadsheetId, sheetName, placeNameColumn, latColumn, lngColumn, geocodingService = getGoogleGeocode) {

  const ss = SpreadsheetApp.getActiveSpreadsheet(); // Get active spreadsheet
  const sheet = ss.getSheetByName(sheetName);
  const dataRange = sheet.getDataRange();
  const data = dataRange.getValues();

  // Iterate through each row (assuming headers are in the first row)
  for (let row = 1; row < data.length; row++) {
    const placeName = data[row][placeNameColumn - 1]; // 0-based index for columns

    if (placeName) {  // Only proceed if there's a place name
      const [lat, lng] = geocodingService(placeName); 
      if (lat && lng) {
        sheet.getRange(row + 1, latColumn).setValue(lat);  // +1 for header row
        sheet.getRange(row + 1, lngColumn).setValue(lng);
      } else {
        // Handle cases where geocoding fails (log or display an error indicator)
        Logger.log(`Geocoding failed for: ${placeName}`); 
      }
    }
  }
}

