<?php

function smart_sort_array(array $set, string $order = 'asc'): array {
    /**
     * Sorts an array of associative arrays (with 'name', 'address', 'age' keys) based on 'age', respecting ascending/descending order.
     *
     * @param array $set  The input array of associative sub-arrays.
     * @param string $order 'asc' for ascending, 'desc' for descending (default: 'asc').
     * @return array The sorted array.
     */
    usort($set, function ($a, $b) use ($order) {
        $comparison = $order === 'asc' ? 1 : -1;  // Determine comparison direction
        return $comparison * ($a['age'] - $b['age']); 
    });
    return $set;
}

// Example Usage:
$data = [
    ['name' => 'Alice', 'address' => '...', 'age' => 25],
    ['name' => 'Bob', 'address' => '...', 'age' => 30],
    ['name' => 'Charlie', 'address' => '...', 'age' => 20]
];

$sortedAscending = smart_sort_array($data); // Sorts by age in ascending order (default)
$sortedDescending = smart_sort_array($data, 'desc'); // Sorts by age in descending order

print_r($sortedAscending);
print_r($sortedDescending);
```

